#define BONUS_STAGE_CELL_COUNT 0x120
#define LEVEL_RECORD_BYTES 0x24a
#define LEVEL_ROW_COUNT 0x10
#define LEVEL_COLUMN_COUNT 0x12
#define LEVEL_TILE_WIDTH 16
#define LEVEL_TILE_HEIGHT 8
#define LEVEL_TILE_ORIGIN_X 16
#define LEVEL_TILE_ORIGIN_Y 24
#define LEVEL_PORTAL_ENTRY_CODE 0xf8
#define LEVEL_PORTAL_EXIT_CODE 0xf9
#define LEVEL_MAPPED_TILE_FIRST 0xfa
#define LEVEL_MAPPED_TILE_LAST 0x100
#define LEVEL_DESTRUCTIBLE_TILE_FIRST 1
#define LEVEL_DESTRUCTIBLE_TILE_LAST 0x90
#define MAX_TILE_ART_ID 0x29
#define LEVEL_READY_TIMEOUT_TICKS 0x2e
#define LEVEL_PROMPT_TIMEOUT_TICKS 0x78
#define LEVEL_PROMPT_FALLBACK_TICKS 0x32
#define POINTS_PER_SCORE_UNIT 0x71
#define EXTRA_LIFE_SCORE_STEP 0x7d0

void reset_level(void)
{
    clear_draw_page(page3);
    image_color_depth = 8;
    drawpage = page3;
    ++tileid;
    if (tileid >= MAX_TILE_ART_ID)
        tileid = 0;
    draw_background_tiles();
    copy_screen_span_entry(page3, 0, page2, 0, vga_state.buffer_size_or_draw_parameter);
    if (image_buffer_error_code != 0)
        fatal_exit(image_buffer_error_code, 0);
}

void load_and_draw_level(void)
{
    int column;
    int row;

    image_color_depth = 8;
    drawpage = page2;
    cell_cursor = brick_code_map;
    remaining_brick_count = 0;
    if (bonus_index != 0) {
        for (scratch = 0; scratch < BONUS_STAGE_CELL_COUNT; ++scratch) {
            cell_cursor++->tile_code = 0;
        }
        enemy_spawn_wait_time = bonus_stage_enemy_intervals[bonus_index];
        remaining_brick_count = bonus_stage_brick_counts[bonus_index];
    } else {
        level_data_cursor += level_number * LEVEL_RECORD_BYTES;
        mov_mem(level_data_cursor, (int)&enemy_spawn_wait_time, 2);
        mov_mem(level_data_cursor + 2, (int)spell_slots, 8);
        mov_mem(level_data_cursor + 10, (int)&brick_code_map, 0x240);
        for (row = 0; row < LEVEL_ROW_COUNT; row++) {
            for (column = 0; column < LEVEL_COLUMN_COUNT; column++) {
                current_brick_code = cell_cursor->tile_code;
                if (current_brick_code > 0xff) {
                    current_brick_code = 0xff;
                    cell_cursor->tile_code = (unsigned char)current_brick_code;
                }
                if (current_brick_code >= LEVEL_DESTRUCTIBLE_TILE_FIRST && current_brick_code <= LEVEL_DESTRUCTIBLE_TILE_LAST)
                    ++remaining_brick_count;
                if (current_brick_code >= LEVEL_MAPPED_TILE_FIRST && current_brick_code <= LEVEL_MAPPED_TILE_LAST) {
                    cell_cursor->drop_value = brick_code_mapping[current_brick_code];
                }
                if (current_brick_code == LEVEL_PORTAL_ENTRY_CODE) {
                    portal_start_x = column * LEVEL_TILE_WIDTH + LEVEL_TILE_ORIGIN_X;
                    portal_y_source = row * LEVEL_TILE_HEIGHT + LEVEL_TILE_ORIGIN_Y;
                }
                if (current_brick_code == LEVEL_PORTAL_EXIT_CODE) {
                    portal_exit_xpos = column * LEVEL_TILE_WIDTH + LEVEL_TILE_ORIGIN_X;
                    portal_destination_y = row * LEVEL_TILE_HEIGHT + LEVEL_TILE_ORIGIN_Y;
                }
                if (current_brick_code != 0) {
                    sprite_metadata = brick_art_start + brick_sprite_offsets_first[current_brick_code].image_offset;
                    draw_bob_sprite(sprite_metadata, column * LEVEL_TILE_WIDTH + LEVEL_TILE_ORIGIN_X, row * LEVEL_TILE_HEIGHT + LEVEL_TILE_ORIGIN_Y);
                }
                ++cell_cursor;
            }
        }
    }
}

int wait_level(void)
{
    int level_wait_result;

    init_stage_palette();
    hook_flags_word = (hook_flags_word & 0xfffe) & 0xfffd;
    space_pressed = 0;
    set_image_pages((int)sprite_commands, 0x100, 4, (int)front_page_bufs, (int)back_page_queue);
    while (1) {
        update_mouse();
        advance_tracks();
        queue_draws();
        redraw_image_region(0, 0);
        if (image_buffer_error_code) {
            fatal_exit(image_buffer_error_code, 0);
        }
        show_page();
        wait_for_tick(1);
        handle_s_key();
        if (space_pressed || (mouse_btn != mouse_btn_old && mouse_btn) || keyboard_scan_byte == 1 || tick >= LEVEL_READY_TIMEOUT_TICKS) break;
    }
    if (tick == LEVEL_READY_TIMEOUT_TICKS) {
        level_wait_result = -1;
    } else {
        level_wait_result = 0;
    }
    drawpage = page2;
    tick = LEVEL_READY_TIMEOUT_TICKS;
    advance_tracks();
    queue_draws();
    redraw_image_region(0, 0);
    copy_screen_span_entry(page2, 0, src_page, 0, vga_state.buffer_size_or_draw_parameter);
    copy_screen_span_entry(page2, 0, dst_page, 0, vga_state.buffer_size_or_draw_parameter);
    set_image_pages((int)sprite_commands, 0x100, 4, (int)front_page_bufs, (int)back_page_queue);
    return level_wait_result;
}

void init_stage_palette(void)
{
    set_page();
    sprite_base = tile_art_base;
    transition_track_data = (struct TransitionTrack *)&level_palette_transition_tracks;
    path_count = 12;
    init_tracks();
    clear_draw_page(src_page);
    clear_draw_page(dst_page);
    write_vga_palette(palette_base);
}

void entry_prompt(void)
{
    set_page();
    transition_track_data = (struct TransitionTrack *)&level_number_transition_tracks_a;
    write_level_number_glyphs();
    await_input(0x78);
    if (tick == LEVEL_PROMPT_TIMEOUT_TICKS) {
        transition_track_data = (struct TransitionTrack *)&level_prompt_fallback_tracks;
        write_level_number_glyphs();
        if (image_buffer_error_code != 0)
            fatal_exit(image_buffer_error_code, 0);
        await_input(LEVEL_PROMPT_FALLBACK_TICKS);
    }
    copy_screen_span_entry(page2, 0, src_page, 0, vga_state.buffer_size_or_draw_parameter);
    copy_screen_span_entry(page2, 0, dst_page, 0, vga_state.buffer_size_or_draw_parameter);
}

void write_level_number_glyphs(void)
{
    sprite_base = fill_sprite_data;
    path_count = 6;
    init_tracks();
    transition_track_data[2].auxiliary = level_digit_sprite_records[(((int)level_number + 1) / 10) % 10].sprite_offset;
    transition_track_data[4].auxiliary = level_digit_sprite_records[((int)level_number + 1) % 10].sprite_offset;
}

void redraw_level_state(void)
{
    stop_audio_stream();
    prep_level();
    copy_screen_span_entry(page2, 0, src_page, 0, vga_state.buffer_size_or_draw_parameter);
    copy_screen_span_entry(page2, 0, dst_page, 0, vga_state.buffer_size_or_draw_parameter);
    move_mouse_to(racket_object->x, racket_object->y);
}

void prepare_game_asset_read(void)
{
    sprite_base = fill_sprite_data;
    path_count = 4;
    set_page();
    init_tracks();
}

void draw_status(void)
{
    configure_text_renderer((int)monster_font_glyph_metrics, monster_art, 0, 8, 8);
    set_text_clip_rect(vga_state.viewport_left, vga_state.viewport_top, vga_state.viewport_right_or_width, vga_state.viewport_bottom_or_height);
    drawpage = page2;
    score_state->opaque_08 = -1;
    score_state->tail = -1;
    draw_zero_padded_number(0x38, 4, score_state->score, 10, 6);
    draw_zero_padded_number(0x99, 4, score_state->life_balance / POINTS_PER_SCORE_UNIT, 10, 2);
    draw_zero_padded_number(0x108, 4, high_score_values, 10, 6);
    copy_screen_span_entry(page2, 0, src_page, 0, vga_state.buffer_size_or_draw_parameter);
    copy_screen_span_entry(page2, 0, dst_page, 0, vga_state.buffer_size_or_draw_parameter);
    drawpage = src_page;
}

void update_game_status_panel(void)
{
    unsigned char saved_draw_page;
    int saved_image_color_depth;

    saved_draw_page = (unsigned char)drawpage;
    saved_image_color_depth = image_color_depth;
    image_color_depth = 8;
    if (next_extra_life_score < score_state->score) {
        score_state->life_balance += POINTS_PER_SCORE_UNIT;
        next_extra_life_score += EXTRA_LIFE_SCORE_STEP;
        submit_audio_request(0x3c);
    }

    if (score_state->score != score_state->tail || score_state->life_balance != score_state->opaque_08) {
        configure_text_renderer((int)monster_font_glyph_metrics, monster_art, 0, 8, 8);
    }
    set_text_clip_rect(vga_state.viewport_left, vga_state.viewport_top, vga_state.viewport_right_or_width, vga_state.viewport_bottom_or_height);

    if (score_state->score != score_state->tail) {
        score_state->tail = score_state->score;
        drawpage = page2;
        draw_zero_padded_number(0x38, 4, score_state->score, 10, 6);
        copy_clipped_screen_rectangle(page2, 0x38, 4, 0x66, 0xb, src_page, 0x38, 4);
        copy_clipped_screen_rectangle(page2, 0x38, 4, 0x66, 0xb, dst_page, 0x38, 4);
    }

    if (score_state->life_balance != score_state->opaque_08) {
        score_state->opaque_08 = score_state->life_balance;
        drawpage = page2;
        draw_zero_padded_number(0x99, 4, score_state->life_balance / POINTS_PER_SCORE_UNIT, 10, 2);
        copy_clipped_screen_rectangle(page2, 0x99, 4, 0xa6, 0xb, src_page, 0x99, 4);
        copy_clipped_screen_rectangle(page2, 0x99, 4, 0xa6, 0xb, dst_page, 0x99, 4);
    }

    drawpage = saved_draw_page;
    image_color_depth = saved_image_color_depth;
}

void process_brick_hit(int column, int cell_index, int velocity_x, int velocity_y)
{
    unsigned char saved_draw_page;
    int pixel_x;
    int pixel_y;

    saved_draw_page = (unsigned char)drawpage;
    pixel_x = column * LEVEL_TILE_WIDTH + LEVEL_TILE_ORIGIN_X;
    pixel_y = cell_index / 18 * 8 + 24;
    score_state->score += 1 << racket_object->reward_level;
    drawpage = page2;
    copy_tile_to_page(pixel_x, pixel_y);
    drawpage = src_page;
    copy_tile_to_page(pixel_x, pixel_y);
    drawpage = dst_page;
    copy_tile_to_page(pixel_x, pixel_y);

    if (velocity_x == 0 && velocity_y == 0) {
        velocity_x = -1;
        velocity_y = -1;
        if ((frames & 8) != 0)
            velocity_x = -velocity_x;
    }

    spawn_animated_sprite(pixel_x, pixel_y, velocity_x, velocity_y, brick_art_start,
           &brick_sprite_offsets_remaining[current_brick_code - 1], 0x12);
    if (current_brick_code >= 0x31 && current_brick_code <= 0x60) {
        if (cell_cursor[column].drop_value) {
            spawn_falling_spell(cell_cursor[column].drop_value - 1, cell_cursor[column].drop_kind, pixel_x + 8, pixel_y + 4);
        }
    }
    cell_cursor[column].tile_code = 0;
    if (current_brick_code >= LEVEL_DESTRUCTIBLE_TILE_FIRST && current_brick_code <= LEVEL_DESTRUCTIBLE_TILE_LAST)
        --remaining_brick_count;
    drawpage = saved_draw_page;
}

void draw_level_tile_on_pages(int column, int cell_index, int tile_id)
{
    unsigned char saved_draw_page;
    int pixel_x;
    int pixel_y;
    int saved_image_color_depth;

    saved_draw_page = (unsigned char)drawpage;
    saved_image_color_depth = image_color_depth;
    image_color_depth = 8;
    pixel_x = column * LEVEL_TILE_WIDTH + LEVEL_TILE_ORIGIN_X;
    pixel_y = cell_index / LEVEL_COLUMN_COUNT * LEVEL_TILE_HEIGHT + LEVEL_TILE_ORIGIN_Y;
    sprite_metadata = brick_art_start + brick_sprite_offsets_first[tile_id].image_offset;
    drawpage = page2;
    draw_bob_sprite(sprite_metadata, pixel_x, pixel_y);
    drawpage = src_page;
    draw_bob_sprite(sprite_metadata, pixel_x, pixel_y);
    drawpage = dst_page;
    draw_bob_sprite(sprite_metadata, pixel_x, pixel_y);
    image_color_depth = saved_image_color_depth;
    drawpage = saved_draw_page;
}

void copy_tile_to_page(int pixel_x, int pixel_y)
{
    copy_clipped_screen_rectangle(page3, pixel_x, pixel_y, pixel_x + 15, pixel_y + 7, drawpage, pixel_x, pixel_y);
}

void refresh_video_pages(int palette_address)
{
    short value;
    if (page_idx != src_page)
        value = src_page;
    else
        value = dst_page;
    drawpage = value;
    copy_screen_span_entry(page2, 0, drawpage, 0, vga_state.buffer_size_or_draw_parameter);
    show_page();
    wait_for_tick(0);
    write_vga_palette(palette_address);
    copy_screen_span_entry(page2, 0, src_page, 0, vga_state.buffer_size_or_draw_parameter);
    copy_screen_span_entry(page2, 0, dst_page, 0, vga_state.buffer_size_or_draw_parameter);
}
